        audit.record("PERIOD_SOFT_CLOSED sheet=" + period.sheetId() + " by=" + input.user()
                + " period=" + period.name() + " total=" + period.closedTotal().toPlainString());
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.crew.CrewRepository;
import net.officefloor.hq.app.person.Grades;
import net.officefloor.hq.app.person.Holds;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.pool.PoolRepository;
import net.officefloor.hq.app.pool.ShownPools;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.statement.Dues;
import net.officefloor.hq.app.statement.LateCharge;

/** Closing a period as a close by hand does, shared by the close and the today change's auto close. */
public final class PeriodCloser {

    private PeriodCloser() {
    }

    /** Close the open or soft-closed period, fixing its due-total and each person's afresh as they are now (as a close
     *  by hand does): the period as closed. Refused when it is already closed. */
    public static Period fix(String id, Period period, PeriodRepository periods, ClaimRepository claims, ClaimLogRepository logs,
            PersonRepository people, RateRepository rates, SettingRepository settings, SheetRepository sheets,
            PoolRepository pools, CrewRepository crews) throws InvalidPeriodException {
        return fix(id, period, false, periods, claims, logs, people, rates, settings, sheets, pools, crews);
    }

    /** Close (or, soft, soft-close) the period, fixing its due-total and each person's due-total and carried figure (see the screen's personPeriodCarried)
     *  as they are now: the period
     *  as closed or soft-closed, and each pool member's cut as the pools show it now. Refused when it is already closed (or, soft, already closed or soft-closed). */
    public static Period fix(String id, Period period, boolean soft, PeriodRepository periods, ClaimRepository claims,
            ClaimLogRepository logs, PersonRepository people, RateRepository rates, SettingRepository settings,
            SheetRepository sheets, PoolRepository pools, CrewRepository crews) throws InvalidPeriodException {
        Map<Long, Person> byId = people.list(id).stream().collect(Collectors.toMap(Person::id, Function.identity()));
        var floor = settings.floor(id);
        LateCharge late = LateCharge.of(id, settings, sheets, claims, people);
        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
        for (Long personId : byId.keySet()) {
            personTotals.put(personId, new BigDecimal("0.00"));
        }
        Map<Long, BigDecimal> personCarried = new LinkedHashMap<>(personTotals);
        var earlier = periods.list(id).stream().filter(p -> p.to().isBefore(period.from())).toList();
        Map<Long, ClaimStatus> atEnd = logs.statusesAt(id, period.to());
        BigDecimal total = new BigDecimal("0.00");
        for (Claim c : claims.list(id)) {
            Person person = byId.get(c.personId());
            ClaimStatus status = atEnd.containsKey(c.id()) ? atEnd.get(c.id()) : c.status();
            if (!Dues.countsAtEnd(c, status, person != null ? person.holds() : Holds.NONE,
                    person != null ? person.retiredFrom() : null, late.today())
                    || !(period.contains(c.dueBy()) || earlier.stream().anyMatch(p -> p.contains(c.dueBy())))) {
                continue;
            }
            if (!period.contains(c.dueBy())) {
                if (person != null && (status == ClaimStatus.OPEN || status == ClaimStatus.PENDING)) {
                    BigDecimal carried = Dues.shown(c, person.grades(), rates, floor, late);
                    if (carried != null) {
                        personCarried.merge(person.id(), carried, BigDecimal::add);
                    }
                }
                continue;
            }
            BigDecimal figure = Dues.shown(c, person != null ? person.grades() : Grades.NONE, rates, floor, late);
            if (figure != null) {
                total = total.add(figure);
                if (person != null) {
                    personTotals.merge(person.id(), figure, BigDecimal::add);
                }
            }
        }
        periods.personOpenings(id).getOrDefault(period.name(), Map.of()).forEach((personId, amount) -> {
            if (personCarried.containsKey(personId)) {
                personCarried.merge(personId, amount, BigDecimal::add);
            }
        });
        if (soft ? !periods.softClose(period, total, personTotals, personCarried)
                : !periods.close(period, total, personTotals, personCarried)) {
            throw new InvalidPeriodException("The period " + period.name() + " is already closed.");
        }
        pools.fixCuts(id, period.name(), ShownPools.list(id, null, pools, crews, people, sheets, settings));
        return new Period(period.sheetId(), period.name(), period.from(), period.to(), !soft, total, soft, period.cap());
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A sheet's period: a name unique on the sheet and an inclusive from and to date; whether it is closed, and
 *  the due-total fixed when it was closed (null while open); and whether it is soft-closed: its due-total (and each
 *  person's) fixed as a close fixes them, while its claims can still be changed (never both closed and soft); and the
 *  most OPEN or PENDING claims a person may have in it (null: no cap). */
public record Period(String sheetId, String name, LocalDate from, LocalDate to, boolean closed,
        BigDecimal closedTotal, boolean soft, Integer cap) {

    /** Whether this period shares a day with the dates from..to (inclusive). */
    public boolean overlaps(LocalDate from, LocalDate to) {
        return !this.from.isAfter(to) && !from.isAfter(this.to);
    }

    /** Whether the date falls in this period. */
    public boolean contains(LocalDate date) {
        return overlaps(date, date);
    }
}
